word_ladder.brute:
if endWord not in wordList: return 0
queue = deque of (beginWord, 1), visited = {beginWord}
while the queue is not empty:
    (word, length) = pop from the front
    if word == endWord: return length
    for each candidate in wordList:   (scan the whole list to find the neighbours)
        if candidate not visited and candidate differs from word in exactly one letter:
            add candidate to visited, push (candidate, length + 1) to the back
return 0

word_ladder.optimal:
if endWord not in wordList: return 0
buckets = dict pattern -> words, e.g. "h*t" -> [hit, hot, ...]
for each word and each position i: append word to buckets[word with letter i replaced by *]
queue = deque of (beginWord, 1), visited = {beginWord}
while the queue is not empty:
    (word, length) = pop from the front
    if word == endWord: return length
    for each position i:
        for each neighbour in buckets[word with letter i replaced by *]:   (neighbours share a pattern)
            if neighbour not visited:   (mark on push, not on pop)
                add neighbour to visited, push (neighbour, length + 1) to the back
return 0

word_ladder_ii.optimal:
words = set of wordList; if endWord not in words: return []
parents = dict word -> set of words one layer earlier
layer = {beginWord}, found = false; remove beginWord from words
while layer is not empty and not found:   (BFS one layer at a time)
    next_layer = dict word -> its parents, over every unused word one letter away from the layer
    for each word in next_layer:   (remove the whole layer, not word by word)
        remove word from words; parents[word] = next_layer[word]
    layer = keys of next_layer; found = endWord in next_layer
paths = []
build_paths(word, path): if word == beginWord: append reversed path to paths
                         else for each parent of word: build_paths(parent, path + [parent])
if found: build_paths(endWord, [endWord])
return paths

sliding_puzzle.brute:
boards = every permutation of "012345" as a string   (all 720 states)
NEIGHBOURS = grid neighbours of the 6 cells
one_move(a, b) = a and b differ in exactly two cells, one holds '0', and the cells are adjacent
start = board flattened to a string
queue = deque of (start, 0), seen = {start}
while the queue is not empty:
    (state, moves) = pop from the front
    if state == "123450": return moves
    for each other in boards:   (719 failed comparisons per board)
        if other not in seen and one_move(state, other):
            add other to seen, push (other, moves + 1) to the back
return -1

sliding_puzzle.optimal:
NEIGHBOURS = grid neighbours of the 6 cells: [[1,3],[0,2,4],[1,5],[0,4],[1,3,5],[2,4]]
start = board flattened to a string
queue = deque of (start, 0), seen = {start}
while the queue is not empty:
    (state, moves) = pop from the front
    if state == "123450": return moves
    blank = position of '0' in state
    for each cell in NEIGHBOURS[blank]:   (slide a neighbouring tile into the blank)
        next_state = state with characters blank and cell swapped
        if next_state not in seen:
            add next_state to seen, push (next_state, moves + 1) to the back
return -1

bus_routes.optimal:
if source == target: return 0
routes_through = dict stop -> list of routes visiting it   (the implicit adjacency)
queue = deque of (route, 1) for each route through source; seen_routes = those routes
seen_stops = {source}
while the queue is not empty:
    (route, buses) = pop from the front
    for each stop on route:
        if stop == target: return buses
        if stop in seen_stops: continue   (its routes were already enqueued)
        add stop to seen_stops
        for each other route through stop not in seen_routes:
            add other to seen_routes, push (other, buses + 1) to the back
return -1

jump_game_iv.brute:
jumps_to = -1 for every index, jumps_to[0] = 0
queue = deque of [0]
while the queue is not empty:
    i = pop from the front
    if i == n - 1: return jumps_to[i]
    neighbours = [i - 1, i + 1] plus every j != i with arr[j] == arr[i]   (O(n) scan per pop)
    for each j in neighbours:
        if j in bounds and jumps_to[j] == -1:
            jumps_to[j] = jumps_to[i] + 1, push j to the back
return jumps_to[n - 1]

k_similar_strings.brute:
queue = deque of (s1, 0), seen = {s1}
while the queue is not empty:
    (current, swaps) = pop from the front
    if current == s2: return swaps
    for each pair i < j:   (every possible swap, even of positions already correct)
        next_string = current with characters i and j swapped
        if next_string not in seen:
            add next_string to seen, push (next_string, swaps + 1) to the back
return -1

k_similar_strings.optimal:
queue = deque of [s1], seen = {s1}, swaps = 0
while the queue is not empty:
    for each string currently in the queue:   (one layer = one swap)
        current = pop from the front
        if current == s2: return swaps
        i = first position where current[i] != s2[i]   (it must be fixed eventually)
        for each j > i:
            if current[j] == s2[i] and current[j] != s2[j]:   (fixes i without breaking j)
                next_string = current with characters i and j swapped
                if next_string not in seen: add it to seen, push it to the back
    swaps += 1
return -1

shortest_path_in_a_grid_with_obstacles_e.optimal:
if k >= rows + cols - 2: return rows + cols - 2   (the straight Manhattan walk is affordable)
start = (0, 0, k)   (row, col, eliminations left)
queue = deque of [start], seen = {start}, steps = 0
while the queue is not empty:
    for each state currently in the queue:   (one layer = one step)
        (row, col, left) = pop from the front
        if (row, col) is the bottom-right corner: return steps
        for each in-bounds neighbour (new_row, new_col):
            new_left = left - grid[new_row][new_col]   (stepping on a 1 spends one)
            state = (new_row, new_col, new_left)
            if new_left >= 0 and state not in seen:   (same cell, more budget: a new state)
                add state to seen, push it to the back
    steps += 1
return -1

minimum_moves_to_move_a_box_to_their_tar.brute:
start = (box row, box col, player row, player col); target = cell of 'T'
best = {start: 0}; heap = min-heap holding (0, start)
while the heap is not empty:   (Dijkstra over (box, player) states)
    (pushes, state) = pop the smallest   (O(log S) just to order the 0s before the 1s)
    if the box of state is at target: return pushes
    if pushes > best[state]: continue   (a stale heap entry)
    for each direction:
        step = next_state(state, direction): None if blocked, else (new state, 1 if it pushed the box else 0)
        if step is None: continue
        if pushes + cost < best[new state]: best[new state] = pushes + cost, push (pushes + cost, new state)
return -1

minimum_moves_to_move_a_box_to_their_tar.optimal:
start = (box row, box col, player row, player col); target = cell of 'T'
pushes_to = {start: 0}; queue = deque of [start]
while the queue is not empty:   (0-1 BFS: the deque stays sorted, all d then all d + 1)
    state = pop from the front, pushes = pushes_to[state]
    if the box of state is at target: return pushes
    for each direction:
        step = next_state(state, direction): None if blocked, else (new state, 1 if it pushed the box else 0)
        if step is None: continue
        if pushes + cost < pushes_to[new state]:
            pushes_to[new state] = pushes + cost
            if cost == 0: push new state to the FRONT   (same distance: handle it before the rest)
            else: push new state to the back
return -1

alien_dictionary.brute:
letters = every letter in words, in order of first appearance; constraints = empty set of (a, b)
for each adjacent pair of words:
    pair = letters at the first position where they differ
    if pair exists: add pair to constraints
    else if the first word is longer: return ""   ("abc" before "ab" is impossible)
order = ""
while letters is not empty:
    blocked = every b with some (a, b) in constraints where a is still in letters   (rescan all constraints)
    free = the first letter not blocked
    if there is none: return ""   (everyone is blocked: a cycle)
    order += free; remove free from letters
return order

alien_dictionary.optimal:
comes_after = dict letter -> set of letters after it; in_degree = 0 for every letter
for each adjacent pair of words:
    pair = letters (before, after) at the first position where they differ
    if no pair and the first word is longer: return ""   ("abc" before "ab" is impossible)
    if pair and after not in comes_after[before]: add it, in_degree[after] += 1   (count a duplicate once)
queue = deque of every letter with in_degree == 0
order = ""
while the queue is not empty:
    letter = pop from the front; order += letter
    for each follower in comes_after[letter]:   (only the direct successors change)
        in_degree[follower] -= 1
        if in_degree[follower] == 0: push follower to the back
if length of order != number of letters: return ""   (letters left over sit on a cycle)
return order

sort_items_by_groups_respecting_dependen.optimal:
for each item with group -1: give it a fresh group id m, m += 1   (a loner is a group of its own)
item_adjacent, item_in_degree over items; group_adjacent, group_in_degree over groups
for each item and each earlier in before_items[item]:
    append item to item_adjacent[earlier], item_in_degree[item] += 1
    if group[earlier] != group[item]:   (a cross-group edge orders the whole groups)
        append group[item] to group_adjacent[group[earlier]], group_in_degree[group[item]] += 1
topological_order(adjacent, in_degree) = Kahn's BFS; [] when some node never reaches in-degree 0
item_order = topological_order(items), group_order = topological_order(groups)
if either is empty: return []   (a cycle among items or among groups)
members[g] = items of group g in item_order
result = members[g] for each g in group_order, concatenated
return result
